for(name,case)in a["cases"].as_object().unwrap(){let raw=fs::read_to_string(r(format!("runs/{name}/stdout.log"))).unwrap();let line=raw.lines().find_map(|l|l.strip_prefix("CENSUS ")).unwrap();assert_eq!(serde_json::from_str::<Value>(line).unwrap(),*case);assert_eq!(case["independent_complete_MSM_hash_matches"],true);let mut totals=BTreeMap::<String,u64>::new();let mut normalized=0;for row in case["rows"].as_array().unwrap(){let size=n(row,"batch_size");let mut initializations=0;let components=row["components"].as_array().unwrap();assert_eq!(components.len(),2);for(comp,c)in components.iter().enumerate(){assert_eq!(n(c,"terms"),n(c,"first_writes")+n(c,"affine_updates")+n(c,"flush_points")+n(c,"equal_x_same")+n(c,"equal_x_opposite"));assert_eq!(n(c,"queue_pushes"),n(c,"drained")+n(c,"flush_points"));assert_eq!(n(c,"projective_arrivals"),n(c,"flush_points")+n(c,"equal_x_same"));assert_eq!(n(c,"projective_arrivals"),n(c,"projective_initializations")+n(c,"projective_adds"));assert_eq!(n(c,"affine_updates"),n(c,"vector_pairs")+n(c,"scalar_tail_pairs"));assert!(n(c,"max_batch")<=size&&n(c,"max_queue")<size);let hist=row["batch_histograms"][comp].as_object().unwrap();assert_eq!(hist.values().map(|v|v.as_u64().unwrap()).sum::<u64>(),n(c,"batches"));assert_eq!(hist.iter().map(|(k,v)|k.parse::<u64>().unwrap()*v.as_u64().unwrap()).sum::<u64>(),n(c,"affine_updates"));assert_eq!(hist.get(&size.to_string()).map(|v|v.as_u64().unwrap()).unwrap_or(0),n(c,"full_batches"));for(k,v)in c.as_object().unwrap(){let v=v.as_u64().unwrap();let t=totals.entry(k.clone()).or_default();if k=="max_batch"||k=="max_queue"{*t=(*t).max(v);}else{*t+=v;}}initializations+=n(c,"projective_initializations");}assert_eq!(n(row,"normalized_projective_points"),initializations);normalized+=initializations;row_count+=1;}
assert_eq!(serde_json::to_value(&totals).unwrap(),case["totals"]);assert_eq!(normalized,n(case,"normalized_projective_points"));assert_eq!(n(&case["global"],"reduction_generic_pairs"),n(&case["global"],"reduction_vector_pairs")+n(&case["global"],"reduction_scalar_tail_pairs"));per_case.insert(name.clone(),json!({"totals":totals,"normalized":normalized,"global":case["global"]}));}
